                                     const Ip6::MessageInfo &aMessageInfo,
                                     StateTlv::State         aState)
{
    otError                  error = OT_ERROR_NONE;
    StateTlv                 state;
    CommissionerSessionIdTlv sessionId;
    Coap::Message *          message;
